let impbtn = document.getElementById("impbtn");
let obs = document.getElementById("observation");
let expkeys = document.getElementById("expkeys");

let currentUser = null;

function serializeForm(formNode) {
  const { elements } = formNode;

  const result = {};

  Array.from(elements).forEach((element) => {
    let { id, type } = element;

    let value = type === "checkbox" ? element.checked : element.value;

    if (id === "tags") {
      value = value ? value.split(",").map((e) => e.trim()) : [];
    }
    result[id] = value;
  });

  currentUser = {
    id: Date.now(),
    userName: result.userName,
    age: Number(result.age),
    isStudent: result.isStudent,
    tags: result.tags,
    profile: {
      city: result.city,
      group: result.group,
      contacts: {
        email: result.email,
      },
    },
    createdAt: new Date(),
  };
}

mainForm.addEventListener("submit", function (e) {
  e.preventDefault();
  serializeForm(mainForm);
});

expbtn.addEventListener("click", function () {
  let space = 0;
  if (document.getElementById("two").checked) space = 2;
  if (document.getElementById("four").checked) space = 4;

  let problemFields = document.getElementById("problemFields");

  let copyOfCurUs = { ...currentUser };

  if (problemFields.checked) {
    copyOfCurUs.temp = undefined;
    copyOfCurUs.calc = function () {
      a + b;
    };
    copyOfCurUs.score = NaN;
    copyOfCurUs.createdAt = new Date();

    obs.textContent = `
