функции исчезают
NaN становятся null
Date превращается в строку`;

    return (outForm.value = JSON.stringify(copyOfCurUs, null, space));
  }

  outForm.value = JSON.stringify(currentUser, null, space);
});

let copyOfCurUs = { ...currentUser };
let checkbox = document.querySelectorAll(".chk:checked");
let ch = Array.from(checkbox).map((inp) => inp.value);
