impbtn.addEventListener("click", function () {
  try {
    let parsed = JSON.parse(outImp.value);

    user.value = parsed.userName;
    age.value = parsed.age;
    isStudent.checked = parsed.isStudent;
    city.value = parsed.profile.city;
    group.value = parsed.profile.group;
    email.value = parsed.profile.contacts.email;
    tags.value = parsed.tags.join(", ");
  } catch (error) {
    alert("некорректный JSON: " + error.message);
